```python
def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])
    bg_color = grid[0][0]

    # Check if there's any feature color
    feature_color = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                feature_color = grid[r][c]
                break
        if feature_color:
            break

    if not feature_color:
        return grid

    # Mark background pixels connected to boundary (outside)
    import collections
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    queue = collections.deque()

    # Add all boundary background pixels
    for c in range(cols):
        if grid[0][c] == bg_color:
            visited[0][c] = True
            queue.append((0, c))
        if grid[rows-1][c] == bg_color:
            visited[rows-1][c] = True
            queue.append((rows-1, c))
    for r in range(rows):
        if grid[r][0] == bg_color:
            visited[r][0] = True
            queue.append((r, 0))
        if grid[r][cols-1] == bg_color:
            visited[r][cols-1] = True
            queue.append((r, cols-1))

    # BFS to find all connected background pixels to boundary
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Fill enclosed background regions with 2
    new_grid = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] == bg_color:
                new_grid[r][c] = 2

    return new_grid
